#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <torch/extension.h>

// Reference streaming kernel with the same access shape as the LN candidate:
// one warp per 1024-element row, 4 x 16 B per thread per stream, 4 streams.

constexpr int kWarpSize = 32;
constexpr int kWarpsPerBlock = 2;
constexpr int kThreads = kWarpSize * kWarpsPerBlock;
constexpr int kRow = 1024;
constexpr int kHalvesPerVec = 8;
constexpr int kHalvesPerWarp = kWarpSize * kHalvesPerVec;
constexpr int kVectorsPerThread = kRow / kHalvesPerWarp;

__global__ __launch_bounds__(kThreads) void row_copy(
    const uint4* __restrict__ a, const uint4* __restrict__ b, uint4* __restrict__ c,
    uint4* __restrict__ d, int rows) {
  const int lane = threadIdx.x % kWarpSize;
  const int row = blockIdx.x * kWarpsPerBlock + threadIdx.x / kWarpSize;
  if (row >= rows) return;
  const size_t base = size_t(row) * (kRow / kHalvesPerVec) + lane * (kHalvesPerVec / 8);
  constexpr int kStride = kHalvesPerWarp / kHalvesPerVec;
#pragma unroll
  for (int i = 0; i < kVectorsPerThread; ++i) {
    const uint4 av = a[base + i * kStride];
    const uint4 bv = b[base + i * kStride];
    c[base + i * kStride] = av;
    d[base + i * kStride] = bv;
  }
}

void run(const torch::Tensor& a, const torch::Tensor& b, const torch::Tensor& c,
         const torch::Tensor& d) {
  const int rows = int(a.numel() / kRow);
  const int blocks = (rows + kWarpsPerBlock - 1) / kWarpsPerBlock;
  row_copy<<<blocks, kThreads, 0, at::cuda::getCurrentCUDAStream()>>>(
      reinterpret_cast<const uint4*>(a.data_ptr()),
      reinterpret_cast<const uint4*>(b.data_ptr()),
      reinterpret_cast<uint4*>(c.data_ptr()), reinterpret_cast<uint4*>(d.data_ptr()),
      rows);
}

